from pathlib import Path
import re,json
R=Path.cwd(); D=R/'research/2026-11-14_astra_lean-check'
# Ordered exactly as the advertised 29 results; each entry has its own statement comparison.
rows=[
('FiniteDifference','finite_difference','4.7','stronger','Any finite index set and any commutative ring. Both the below-degree zero and top-degree factorial product are proved. The paper is the real specialisation; no positivity of steps is required.'),
('FiniteDifference','finite_difference_fin','4.7','stronger','Same two conclusions on Fin c, for any commutative ring. Subsets encode bit strings bijectively. Degenerate rings are allowed but do not weaken the real instance.'),
('LocalSign','prod_sum_of_signs','proof of 4.4','stronger','For any finite family of integer signs, gives both the product by negative-factor count and the sum/count identity. This is the arithmetic subclaim used in the paper, independent of geometry.'),
('LocalSign','paperSign_reverse','4.4 first reversal','faithful','A partner r, actual opposite cycle C, and its delta sum ±3 imply sign reversal. The disk premise is explicit for arbitrary triangle systems and is discharged in the concrete theorem. Not an unconditional theorem about arbitrary systems.'),
('LocalSign','paperSign_partners_sum','4.5 first sentence','stronger','Cancels the partners of one state for an arbitrary additive commutative group and constant group-valued weight. Requires the disk identity for all partners on the chosen cycle. The unweighted integer sum is the instance weight=1.'),
('LocalSign','sign_orient','4.4 second reversal','faithful','All cycle delta sums ±3; orient swaps the two corners on exactly the selected permutation orbits. The conclusion counts selected orbits, not faces.'),
('LocalSign','sign_reverse_one','4.4 second reversal','faithful','Specialises the preceding theorem with a Boolean function true exactly on the specified orbit. Such a Boolean function exists classically on the finite quotient; the condition is not contradictory.'),
('LocalSign','sign_formula','4.4 closed formula','faithful','Even(n+c) and the stated integer sign exponent; ccwCount is the count of orbits whose delta sum is -3. This equals geometric counterclockwise count only with the aligned orientation convention.'),
('LocalSign','I_zpow_rawIndexSum','arithmetic behind 4.10','stronger','Every partner pair gives i^(raw sum)=i^n epsilon, without divisibility or disk hypotheses. Uses integer exponent on the left and natural exponent on i^n.'),
('LocalSign','phase_eq_paperSign','4.10 phase sentence','faithful','Requires 3 divides the raw sum, avoiding the truncating integer division trap in phase. Proves phase=i^(-n)epsilon.'),
('LocalSign','paperSign_eq_I_pow_mul_phase','4.10 phase sentence','faithful','Equivalent rearrangement epsilon=i^n phase with exactly the same partner and divisibility hypotheses.'),
('LocalSign','three_dvd_rawIndexSum','disk input to 4.10','faithful','Cycle delta sums ±3 imply divisibility of the total by 3, using the actual orbit partition of the state permutation.'),
('LocalSign','sign_eq_I_pow_mul_phase','4.10 phase sentence','faithful','Combines the two preceding inputs for a Pair. Does not assert a height/flow correspondence or a polynomial identity with different weights.'),
('RealSign','sum_sign_eq_zero_of_no_good','4.5 second sentence','weaker','Proves only the no-acyclic-partner case: if every pair has cyclic Q_right, the total weighted sum is zero. The paper states the full equality to a sum over good states, with their unique partners. Neither that equality nor partner uniqueness is proved here. README table acknowledges the case used, but its later whole-lemma claim is too broad.'),
('RealSign','weight_orient','4.6 additivity used in 4.8','different','Exact algebraic additivity for arbitrary real local weights w and step=-cycleSlope. No face paths, per-face heights, positive integer white-face count, or equality to the paper weights occurs. If original delta=-3, slope>0 and reversing gives a negative step; positive steps are from clockwise to counterclockwise, as in the current paper.'),
('RealSign','group_sum','4.8 class calculation','faithful','On Group defined by fixed third corner at each face, the weighted real-sign sum equals epsilon(P) times the finite difference at the chosen representative. Uses exact orient/groupEquiv, not a newly invented quotient.'),
('RealSign','group_sum_card','4.8 minimum-size class calculation','faithful','With m equal to this pair orbit count, gives the common sign times m! times the product of absolute slopes. Strict slope signs are explicit. Geometric L and its integrality are not asserted; absolute slopes play that role.'),
('RealSign','group_sum_lt','4.8 larger-class calculation','faithful','The class contribution vanishes for m less than its orbit count, for arbitrary local real weights. No positivity premise is needed in this case.'),
('RealSign','realSum_ne_zero','4.8 nonvanishing','different','Nonempty Pair and strict signed slopes imply nonzero realSum at minCycles over chosen class representatives. The formal conclusion is only nonzero, not the full equality advertised in its docstring. Equality appears inside the proof. Identification of this m with the minimum over all pairs remains T1.'),
('RealSign','forest_pair_of_disk_circulation_real','4.8 existence','faithful','Same abstract hypotheses and conclusion as upstream: nonempty Pair, every opposite disk identity, and a local real weight with the strict cycle-sign condition imply a pair with acyclic opposite graph. Paper good state includes one root per component, so translating the conclusion still uses B4. This does not define good state to make existence automatic.'),
('Concrete','sign_reverse_opposite','4.4 first reversal','faithful','Specialises to any ColoredDual and partner pair; obtains disk hypotheses from upstream. Unconditional means relative to this substantial structure, not for every arbitrary graph.'),
('Concrete','sign_orient_concrete','4.4 second reversal','faithful','For a pair of the concrete system and arbitrary Boolean orbit selection. Finite V,E,F and ColoredDual encode the geometric/algebraic setting.'),
('Concrete','sign_formula_concrete','4.4 closed formula','faithful','Counts nonroot black vertices and permutation cycles. Root need not have an explicit black proof in the binders; a pair is still required. No extra positivity or nonemptiness is hidden in the instance arguments.'),
('Concrete','sign_eq_I_pow_mul_phase_concrete','4.10 phase sentence','faithful','Every supplied pair satisfies epsilon=i^n phase, with n=card Black(root). The orientation comparison to a drawing is informal; relative to indexDelta this is exact.'),
('Concrete','forest_pair_real','4.8 existence','faithful','Nonempty concrete Pair implies existence of a pair with acyclic Q_right. Same statement as upstream forest_pair. Finite-type and ColoredDual premises remain; README wording no hypotheses left is only about disk and circulation premises.'),
('Concrete','realSum_ne_zero_concrete','4.8 nonvanishing','different','Requires Nonempty Pair and a supplied real edge flow alpha with boundary whiteCharge. Its weight is M.weights alpha root. Neither arbitrary zero weights nor paper face-path heights are substituted without proof.'),
('Outdegree','card_edgeSet_add_sinks','3.7 edge count','stronger','Every finite simple graph with OutOrientation satisfies edges+sinks=vertices, without connectedness. out_adj,covers,one_way ensure exactly one chosen tail per edge.'),
('Outdegree','component_count','3.7 component conclusions','weaker','For one finite connected graph, gives the count, at most one sink, tree if one sink, and if zero sinks a cycle exists and deleting any nonbridge edge leaves a tree. This faithfully encodes the component conclusions, but omits the lemma first sentence that every cycle is directed, and does not apply the orientation to Q_s.'),
('TreeMatching','perfectMatching_unique','Section 7 which cycles arise; also Section 3 prose','faithful','Finite graph, acyclic, two perfect-matching subgraphs imply equality. Perfectness includes spanning, so isolated vertices do not create false witnesses. It is a uniqueness theorem, not existence and not the complete recovery/injectivity remark.')]
assert len(rows)==29
intro='''# Statement faithfulness\n\nStatus: COMPUTED for compiled Lean statements; PROVED-HERE for the elementary comparisons and sign algebra. This audit compares the frozen working-tree paper in `paper-at-review.tex.txt`, not an earlier author commit. The relevant labels still resolve to Lemmas 3.7, 4.4--4.7, Proposition 4.8 and Remark 4.10, as recorded in `paper-labels.txt`.\n\n## Definitions and scope\n\nAll generic triangle results have types A,V, a TriangleSystem T, and a set X of allowed vertices. Fintype A supplies an enumeration of faces, not a Nonempty A instance. TriangleSystem has three distinct vertices per face and forbids distinct faces sharing the same side. A State is a corner function whose selected vertices are injective and have range exactly X. Thus it is an incidence-constrained bijection A to X. Partner means different selected vertices at every face; Pair is the subtype of ordered state pairs with that property. These are upstream definitions, unchanged.\n\nindexDelta on Fin 3 is 0 on equal indices, +1 on cyclic successors, -1 otherwise. On pairs it is ±1. paperSign is the integer product over all faces, not a new arbitrary sign. The witness Nonvacuity.lean supplies a nonempty three-face model and both sign values. numerical.py checks actual sphere triangulations and has 136 ordered pairs across all face rootings.\n\nPair.next is right.toEquiv followed by left.toEquiv inverse. CycleClass is the quotient of A by permutation SameCycle, not a singleton surrogate. A fixed point is impossible for a pair. cycleFaces is the fiber of this quotient map. cycleDelta sums local deltas there. Group fixes the unused third corner at each face, hence the same undirected chosen side. orient swaps left and right on whole orbits. groupEquiv is upstream's bijection between Boolean orbit choices and this fiber. GroupIndex is the range of the third-corner map; representative uses Classical.choose of a pair witnessing membership. minCycles minimises the orbit count of those representatives.\n\nOppositeGraph has an edge between the two corners not selected by the state. OppositeCycle contains an injective genuine graph cycle of length at least three and distinct incident faces. Upstream oppositeCycle_nonempty derives one from failure of IsAcyclic. Mathlib IsAcyclic says that no closed walk is a cycle. In particular an isolated vertex does not by definition make a graph non-acyclic. The paper's good state additionally requires exactly one root in every component. Acyclicity alone is not equivalent for an arbitrary state, as the prism example confirms. Existence theorems here also retain a partner, which is essential for the B4 bridge.\n\nweight w s is the sum of w(t,s(t)). cycleSlope is sum w(t,right(t)) minus sum w(t,left(t)) on one orbit; step is its negative. realSum is the sum over all actual pairs of the integer sign, cast to reals, times weight(right)^m. For a nonempty face set and an actual pair, there is an orbit and the strict slope premise rules out identically zero local weights. Empty A is allowed, consistently: the unique empty pair has m=0, sign=1 and weight^0=1. No false universal nonvanishing for zero weights is claimed.\n\nConcrete results quantify finite vertex, edge and dual-vertex types and M : N.ColoredDual D. Network gives edge endpoints. Duality contains connectivity of both graphs and the two cycle-space/cut-space equalities over the reals. ColoredDual adds simplicity of both networks, cubicity, a bipartition, a triangle in D for every primal vertex, and compatible orientation. It does not contain a Hamiltonicity or good-state existence field. Black(root) is black vertices other than root. nonroots is the complement of the root triangle's corners. system uses the triangles at Black(root). weights are triangle potentials of alpha. whiteCharge has charge 1 on white vertices and balancing negative charge at root. The current proofs obtain a flow from connectivity and zero total charge, rather than assume the desired conclusion.\n\nFinite/ Fintype and DecidableEq arguments are standard finite enumeration/equality assumptions. Classical instances supply decisions without restricting the allowed finite objects. Nonempty Pair is explicit in all nonvanishing and existence results. The concrete hypotheses are satisfiable in the intended sphere examples; the full geometry-to-algebra dictionary is accepted upstream background, not re-formalised here.\n\nVerdicts below concern each advertised part under this dictionary. A faithful algebraic theorem is not a machine-checked theorem about the paper's unformalised sphere object. Formal headers are quoted from submitted source; imported namespaces and the common parameters above are part of each header. Independently elaborated full types are saved in statements.out.\n'''
parts=[intro]
for i,(file,name,paper,verdict,why) in enumerate(rows,1):
 src=(R/f'proofs/lean/Devices/{file}.lean').read_text(encoding='utf-8')
 pattern=r'(?:theorem|lemma) (?:[\w.]*\.)?'+re.escape(name)+r'\b'
 m=re.search(pattern,src);assert m,name
 end=src.index(':=',m.start())
 header=src[m.start():end].rstrip()
 parts.append(f'\n## {i}. {name}\n\nFormal source: `Devices/{file}.lean`, line {src[:m.start()].count(chr(10))+1}.\n\n```lean\n{header}\n```\n\nPaper counterpart: {paper}. Verdict: **{verdict}**. {why}\n')
parts.append('''\n## Whole-package qualifications\n\nThe 29-entry list names headline results, not every new declaration. Auxiliary lemmas and definitions are also in the compiled files. Axiom closure of a headline result includes its used auxiliaries. No claim here says that every lemma in Mathlib has been independently audited.\n\nThe README's claim that all of Lemma 4.5 is checked is too broad: its second sentence is only proved in the no-good-pair case. Its counterclockwise-positive-L wording also needs correction: step=-slope is positive when reversing an originally clockwise cycle. The current paper states that direction correctly. The formal existence result is unaffected.\n\nTODO T5 is false as written. It strengthens “a cycle is produced iff its recovered state is good” to “every eligible Hamiltonian cycle has a good recovered state”. The hexagonal-prism enumeration gives four eligible cycles, two with non-good recovered state. See numerical.json and REPORT.md. Consequently the all-checks condition for updating canonical statuses is not met.\n''')
(D/'FAITHFULNESS.md').write_text(''.join(parts),encoding='utf-8')
(D/'theorem-review.json').write_text(json.dumps([dict(zip(['file','name','paper','verdict','reason'],r)) for r in rows],indent=2)+'\n',encoding='utf-8')
print('Wrote',len(rows),'individual reviews')
